'use strict'

const childProcess = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')

// Hermes Runtime creates this checkout-local stamp after its launch-time
// stale-bytecode sweep. It contains only the current Git ref/commit
// fingerprint and is regenerated by the Runtime itself. It is the only
// untracked path an already-launched diagnostic Runtime may carry.
const GENERATED_RUNTIME_CACHE_STATUS = '?? .bytecode-fingerprint'
const GENERATED_RUNTIME_FINGERPRINT = /^git:(?:HEAD|refs\/[^:\r\n]+):(?:[0-9a-f]{40}|unresolved)$/

function unexpectedRuntimeStatusEntry(status) {
  const entries = String(status)
    .split('\0')
    .filter(Boolean)

  return entries.find(entry => entry !== GENERATED_RUNTIME_CACHE_STATUS) || null
}

function assertDiagnosticRuntimeClean(
  runtimeRoot,
  execFileSync = childProcess.execFileSync,
  lstatSync = fs.lstatSync
) {
  const status = execFileSync(
    'git',
    ['-C', runtimeRoot, 'status', '--porcelain=v1', '-z', '--untracked-files=all'],
    { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }
  )
  const unexpected = unexpectedRuntimeStatusEntry(status)

  if (unexpected) {
    throw new Error(`Runtime worktree is not clean; first unexpected entry: ${unexpected}`)
  }

  const generatedCachePath = path.join(runtimeRoot, '.bytecode-fingerprint')

  try {
    const cacheStat = lstatSync(generatedCachePath)

    if (cacheStat.isSymbolicLink() || !cacheStat.isFile()) {
      throw new Error('Runtime-generated .bytecode-fingerprint must be a regular non-symlink file')
    }

    if (!String(status).split('\0').includes(GENERATED_RUNTIME_CACHE_STATUS)) {
      throw new Error('Runtime-generated .bytecode-fingerprint must remain an untracked root cache')
    }

    const fingerprint = fs.readFileSync(generatedCachePath, 'utf8')

    if (!GENERATED_RUNTIME_FINGERPRINT.test(fingerprint)) {
      throw new Error('Runtime-generated .bytecode-fingerprint does not contain a Git checkout fingerprint')
    }
  } catch (error) {
    if (error && error.code === 'ENOENT') {
      return
    }

    throw error
  }
}

module.exports = {
  assertDiagnosticRuntimeClean,
  GENERATED_RUNTIME_FINGERPRINT,
  GENERATED_RUNTIME_CACHE_STATUS,
  unexpectedRuntimeStatusEntry
}
